                                    if not math.isfinite(dx[xi]):
                                        raise ValueError(
                                            "conv2d_batch backward "
                                            "intermediate must be finite"
                                        )
                                    contrib_w = gv * snapshot_x[xi]
                                    if not math.isfinite(contrib_w):
                                        raise ValueError(
                                            "conv2d_batch backward "
                                            "intermediate must be finite"
                                        )
